 private final Instrumentation ins=InstrumentationRegistry.getInstrumentation();private final Context c=ins.getTargetContext();
 private File fixture(String name)throws IOException{File file=File.createTempFile("expansion-",".input",c.getCacheDir());try(InputStream in=ins.getContext().getAssets().open(name);OutputStream out=new FileOutputStream(file)){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}return file;}
 private Object field(Object object,String name)throws Exception{Field f=object.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(object);}
 @Test public void adtsPreservesEveryAacPacketAndCancellation()throws Exception{for(String input:new String[]{"audio.m4a","audio-stereo.m4a","combined.mp4"}){File source=fixture(input),output=File.createTempFile("aac-",".aac",c.getCacheDir());try{AdtsAudio.extract(source,output,()->{});MediaExtractor ex=new MediaExtractor();try{ex.setDataSource(source.getPath());for(int i=0;i<ex.getTrackCount();i++)if("audio/mp4a-latm".equals(ex.getTrackFormat(i).getString(MediaFormat.KEY_MIME))){ex.selectTrack(i);break;}byte[] raw=java.nio.file.Files.readAllBytes(output.toPath());int at=0,packets=0;ByteBuffer buffer=ByteBuffer.allocate(8192);while(at<raw.length){int length=((raw[at+3]&3)<<11)|((raw[at+4]&255)<<3)|((raw[at+5]&224)>>5);assertEquals(255,raw[at]&255);assertTrue(length>=7&&at+length<=raw.length);buffer.clear();int n=ex.readSampleData(buffer,0);assertEquals(n,length-7);byte[] packet=new byte[n];buffer.position(0);buffer.get(packet);assertArrayEquals(packet,Arrays.copyOfRange(raw,at+7,at+length));ex.advance();at+=length;packets++;}assertTrue(packets>50);assertTrue(ex.readSampleData(buffer,0)<0);}finally{ex.release();}try{AdtsAudio.extract(source,output,()->{throw new InterruptedIOException("cancelled");});fail();}catch(InterruptedIOException expected){}}finally{source.delete();output.delete();}}}
 @Test public void publicPageDownloadsRealOriginalAndRecordsItsPage()throws Exception{String url="https://raw.githubusercontent.com/cristianoarakaki-cpu/Arakaki/245b693e64cf5b5b33bc2a5f491a607f6a435655/Onda/tests/fixtures/download.mp4";String html="<title>Onda public page</title><video src='"+url+"'></video>";YoutubeDownloads.Result result=MediaDownloads.fromPublicPage(new PublicMediaHttp.Page("https://example.org/lesson","text/html",html.getBytes()),PublicMediaHttp::readMediaPrefix);YoutubeDownloads.Option option=result.options.get(0);assertTrue(option.original);runService(option,"https://example.org/lesson","mp4");}
 @Test public void foregroundServiceSavesActualAacAudio()throws Exception{YoutubeDownloads.Option option=new YoutubeDownloads.Option("AAC","https://raw.githubusercontent.com/cristianoarakaki-cpu/Arakaki/245b693e64cf5b5b33bc2a5f491a607f6a435655/Onda/tests/fixtures/download.mp4",null,"aac","audio/aac");runService(option,"https://www.youtube.com/watch?v=aqz-KE-bpKQ","aac");}
 private void runService(YoutubeDownloads.Option option,String page,String format)throws Exception{File output=File.createTempFile("public-service-","."+format,c.getCacheDir());String old=c.getSharedPreferences(DownloadHistory.PREF,0).getString("data",null);Intent job=new Intent(c,MediaDownloadService.class).putExtra("first",option.first).putExtra("format",format).putExtra("original",option.original).putExtra("referer",option.referer).putExtra("source",page).putExtra("destination",Uri.fromFile(output).toString()).putExtra("title","Public page fixture");try{c.getSharedPreferences("downloads",0).edit().clear().commit();ins.runOnMainSync(()->c.startForegroundService(job));long until=System.currentTimeMillis()+90000;String status="";while(System.currentTimeMillis()<until){status=c.getSharedPreferences("downloads",0).getString("status","");if(!MediaDownloadService.activeDownload&&(status.startsWith("Download concluído")||status.startsWith("Operação interrompida")))break;Thread.sleep(100);}assertTrue(status,status.startsWith("Download concluído"));MediaExtractor ex=new MediaExtractor();try{ex.setDataSource(output.getPath());assertEquals(format.equals("aac")?1:2,ex.getTrackCount());}finally{ex.release();}assertTrue(DownloadHistory.read(c).stream().anyMatch(e->e.uri.equals(Uri.fromFile(output).toString())&&e.source.equals(page)&&e.state.equals("done")));}finally{c.stopService(job);output.delete();android.content.SharedPreferences.Editor editor=c.getSharedPreferences(DownloadHistory.PREF,0).edit();if(old==null)editor.remove("data");else editor.putString("data",old);editor.commit();}}
 @Test public void youtubeTabUsesOfficialPageAndDestroysBrowserWhenHidden()throws Exception{Activity activity=ins.startActivitySync(new Intent(c,YouTubeActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Intent[] request={null};Instrumentation.ActivityMonitor monitor=new Instrumentation.ActivityMonitor(){@Override public Instrumentation.ActivityResult onStartActivity(Intent intent){if(intent.getComponent()!=null&&intent.getComponent().getClassName().equals(DownloadsActivity.class.getName())){request[0]=intent;return new Instrumentation.ActivityResult(Activity.RESULT_CANCELED,null);}return null;}};ins.addMonitor(monitor);try{ins.runOnMainSync(()->{try{WebView web=(WebView)field(activity,"web");assertNotNull("Android System WebView required",web);assertFalse(web.getSettings().getAllowFileAccess());assertFalse(web.getSettings().getAllowContentAccess());assertTrue(web.getSettings().getMediaPlaybackRequiresUserGesture());assertFalse(CookieManager.getInstance().acceptThirdPartyCookies(web));web.stopLoading();web.loadDataWithBaseURL("https://m.youtube.com/watch?v=aqz-KE-bpKQ","<html><body><h1>Onda • teste da aba YouTube</h1><p>Página de teste local</p></body></html>","text/html","UTF-8","https://m.youtube.com/watch?v=aqz-KE-bpKQ");}catch(Exception e){throw new RuntimeException(e);}});ins.waitForIdleSync();boolean[] browserReady={false};String[] browserState={""};for(int attempt=0;attempt<50;attempt++){ins.runOnMainSync(()->{try{WebView view=(WebView)field(activity,"web");Button button=(Button)field(activity,"formats");browserState[0]="url="+(view==null?"null":view.getUrl())+", enabled="+button.isEnabled()+", status="+((TextView)field(activity,"status")).getText();browserReady[0]=view!=null&&button.isEnabled()&&YouTubeActivity.downloadUrl(view.getUrl()).equals("https://www.youtube.com/watch?v=aqz-KE-bpKQ");}catch(Exception e){throw new RuntimeException(e);}});if(browserReady[0])break;Thread.sleep(200);}Bitmap shot=ins.getUiAutomation().takeScreenshot();if(shot!=null)try(OutputStream out=new FileOutputStream(new File(c.getFilesDir(),"youtube-ui.png"))){shot.compress(Bitmap.CompressFormat.PNG,100,out);}finally{shot.recycle();}assertTrue(browserState[0],browserReady[0]);ins.runOnMainSync(()->{try{((Button)field(activity,"formats")).performClick();assertNotNull("Intent não recebido pelo monitor: "+browserState[0],request[0]);assertEquals("https://www.youtube.com/watch?v=aqz-KE-bpKQ",request[0].getStringExtra("analyze_link"));ins.callActivityOnPause(activity);ins.callActivityOnStop(activity);assertNull(field(activity,"web"));ins.callActivityOnResume(activity);assertNotNull("WebView não voltou: "+((TextView)field(activity,"status")).getText(),field(activity,"web"));}catch(Exception e){throw new RuntimeException(e);}});assertFalse(YouTubeActivity.allowed("https://youtube.com.evil.org/watch?v=aqz-KE-bpKQ"));assertFalse(YouTubeActivity.allowed("file:///sdcard/a.html"));assertTrue(YouTubeActivity.allowed("https://m.youtube.com/"));}finally{ins.removeMonitor(monitor);ins.runOnMainSync(activity::finish);}}
 @Test public void youtubeVoiceButtonSearchesInsideAppAndHandlesCancelAndMissingService()throws Exception{
  String phrase="Chitãozinho e Xororó & ao vivo #1";String expected=YouTubeActivity.searchUrl(phrase);Uri parsed=Uri.parse(expected);assertEquals("m.youtube.com",parsed.getHost());assertEquals("/results",parsed.getPath());assertEquals(phrase,parsed.getQueryParameter("search_query"));assertEquals(1,parsed.getQueryParameterNames().size());assertEquals("",YouTubeActivity.searchUrl("   "));assertEquals("",YouTubeActivity.searchUrl(new String(new char[161]).replace('\0','x')));
  Activity activity=ins.startActivitySync(new Intent(c,YouTubeActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));int[] mode={0};Intent[] speech={null};Instrumentation.ActivityMonitor monitor=new Instrumentation.ActivityMonitor(){@Override public Instrumentation.ActivityResult onStartActivity(Intent intent){if(android.speech.RecognizerIntent.ACTION_RECOGNIZE_SPEECH.equals(intent.getAction())){speech[0]=intent;if(mode[0]==2)throw new ActivityNotFoundException("No speech service fixture");Intent result=new Intent().putStringArrayListExtra(android.speech.RecognizerIntent.EXTRA_RESULTS,new ArrayList<>(Collections.singletonList(phrase)));return new Instrumentation.ActivityResult(mode[0]==0?Activity.RESULT_OK:Activity.RESULT_CANCELED,result);}return null;}};ins.addMonitor(monitor);
  try{ins.runOnMainSync(()->{try{((Button)field(activity,"voice")).performClick();}catch(Exception e){throw new RuntimeException(e);}});boolean[] done={false};for(int i=0;i<50;i++){ins.runOnMainSync(()->{try{done[0]=expected.equals(field(activity,"lastUrl"))&&!((Boolean)field(activity,"recognizing"));}catch(Exception e){throw new RuntimeException(e);}});if(done[0])break;Thread.sleep(100);}assertTrue("Voice result did not reach in-app search",done[0]);ins.runOnMainSync(()->{try{WebView web=(WebView)field(activity,"web");if(web!=null){web.stopLoading();web.setWebViewClient(new WebViewClient());}}catch(Exception e){throw new RuntimeException(e);}});assertNotNull(speech[0]);assertEquals("pt-BR",speech[0].getStringExtra(android.speech.RecognizerIntent.EXTRA_LANGUAGE));assertFalse(speech[0].getBooleanExtra(android.speech.RecognizerIntent.EXTRA_PREFER_OFFLINE,true));assertTrue(speech[0].getStringExtra(android.speech.RecognizerIntent.EXTRA_PROMPT).contains("YouTube"));
   for(int next:new int[]{1,2}){mode[0]=next;ins.runOnMainSync(()->{try{((Button)field(activity,"voice")).performClick();}catch(Exception e){throw new RuntimeException(e);}});for(int i=0;i<50;i++){ins.runOnMainSync(()->{try{done[0]=!((Boolean)field(activity,"recognizing"));}catch(Exception e){throw new RuntimeException(e);}});if(done[0])break;Thread.sleep(100);}assertTrue(done[0]);ins.runOnMainSync(()->{try{assertEquals(expected,field(activity,"lastUrl"));assertEquals(phrase,((EditText)field(activity,"query")).getText().toString());assertTrue(((Button)field(activity,"voice")).isEnabled());assertTrue(((TextView)field(activity,"status")).getText().toString().contains(mode[0]==1?"cancelada":"indisponível"));}catch(Exception e){throw new RuntimeException(e);}});}
  }finally{ins.removeMonitor(monitor);ins.runOnMainSync(activity::finish);}
 }
 @Test public void youtubeVoiceResultSurvivesBrowserStopAndKeepsQueryInSavedState()throws Exception{
  YouTubeActivity activity=(YouTubeActivity)ins.startActivitySync(new Intent(c,YouTubeActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));String phrase="Chitãozinho e Xororó";String expected=YouTubeActivity.searchUrl(phrase);
  try{ins.runOnMainSync(()->{try{ins.callActivityOnPause(activity);ins.callActivityOnStop(activity);assertNull(field(activity,"web"));activity.onActivityResult(VoiceSearch.REQUEST,Activity.RESULT_OK,new Intent().putStringArrayListExtra(android.speech.RecognizerIntent.EXTRA_RESULTS,new ArrayList<>(Collections.singletonList(phrase))));assertEquals(expected,field(activity,"lastUrl"));assertNull(field(activity,"web"));assertFalse(((Button)field(activity,"formats")).isEnabled());android.os.Bundle state=new android.os.Bundle();ins.callActivityOnSaveInstanceState(activity,state);assertEquals(phrase,state.getString("query"));assertEquals(expected,state.getString("url"));ins.callActivityOnResume(activity);WebView web=(WebView)field(activity,"web");assertNotNull(web);assertTrue(web.getSettings().getMediaPlaybackRequiresUserGesture());assertFalse(web.getSettings().getAllowContentAccess());assertEquals(phrase,((EditText)field(activity,"query")).getText().toString());web.stopLoading();web.loadDataWithBaseURL(expected,"<html><body><h2>Busca por voz no Onda</h2><p>Teste local do retorno da voz</p></body></html>","text/html","UTF-8",expected);}catch(Exception e){throw new RuntimeException(e);}});ins.waitForIdleSync();Bitmap shot=ins.getUiAutomation().takeScreenshot();if(shot!=null)try(OutputStream out=new FileOutputStream(new File(c.getFilesDir(),"youtube-voice-ui.png"))){shot.compress(Bitmap.CompressFormat.PNG,100,out);}finally{shot.recycle();}
  }finally{ins.runOnMainSync(activity::finish);}
 }

 private void protection(Activity activity,boolean enabled)throws Exception{java.lang.reflect.Method method=YouTubeActivity.class.getDeclaredMethod("setProtection",boolean.class);method.setAccessible(true);method.invoke(activity,enabled);}
 private WebResourceRequest resource(String url,boolean main){return new WebResourceRequest(){public Uri getUrl(){return Uri.parse(url);}public boolean isForMainFrame(){return main;}public boolean isRedirect(){return false;}public boolean hasGesture(){return false;}public String getMethod(){return "GET";}public Map<String,String> getRequestHeaders(){return Collections.emptyMap();}};}
 @Test public void youtubeProtectionInterceptsOnlyAdvertisingResourcesAndRemembersSwitch()throws Exception{
  SharedPreferences prefs=c.getSharedPreferences(YouTubeProtection.PREF,0);boolean had=prefs.contains(YouTubeProtection.KEY),old=prefs.getBoolean(YouTubeProtection.KEY,true);prefs.edit().putBoolean(YouTubeProtection.KEY,true).commit();Activity[] activity={ins.startActivitySync(new Intent(c,YouTubeActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK))};
  try{ins.runOnMainSync(()->{try{WebView web=(WebView)field(activity[0],"web");web.stopLoading();WebViewClient client=web.getWebViewClient();WebResourceResponse blocked=client.shouldInterceptRequest(web,resource("https://googleads.g.doubleclick.net/pagead/test",false));assertNotNull(blocked);assertEquals(204,blocked.getStatusCode());assertEquals(-1,blocked.getData().read());assertEquals("no-store",blocked.getResponseHeaders().get("Cache-Control"));assertNull(client.shouldInterceptRequest(web,resource("https://doubleclick.net/pagead/test",true)));for(String url:new String[]{"https://rr1.googlevideo.com/videoplayback?ad=1","https://m.youtube.com/results?search_query=Chitao","https://i.ytimg.com/a.jpg","https://notdoubleclick.net/ad"})assertNull(client.shouldInterceptRequest(web,resource(url,false)));protection(activity[0],false);assertNull(client.shouldInterceptRequest(web,resource("https://googleads.g.doubleclick.net/pagead/test",false)));assertFalse(prefs.getBoolean(YouTubeProtection.KEY,true));activity[0].finish();}catch(Exception e){throw new RuntimeException(e);}});activity[0]=ins.startActivitySync(new Intent(c,YouTubeActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));ins.runOnMainSync(()->{try{assertFalse((Boolean)field(activity[0],"protectionEnabled"));WebView web=(WebView)field(activity[0],"web");assertTrue(web.getSettings().getMediaPlaybackRequiresUserGesture());assertFalse(web.getSettings().getAllowFileAccess());assertNull(web.getWebViewClient().shouldInterceptRequest(web,resource("https://doubleclick.net/ad",false)));protection(activity[0],true);assertNotNull(web.getWebViewClient().shouldInterceptRequest(web,resource("https://doubleclick.net/ad",false)));}catch(Exception e){throw new RuntimeException(e);}});
  }finally{ins.runOnMainSync(()->activity[0].finish());SharedPreferences.Editor edit=prefs.edit();if(had)edit.putBoolean(YouTubeProtection.KEY,old);else edit.remove(YouTubeProtection.KEY);edit.commit();}
 }
 private void waitBrowserScript(Activity activity,String script,String expected)throws Exception{java.util.concurrent.atomic.AtomicReference<String> value=new java.util.concurrent.atomic.AtomicReference<>();for(int i=0;i<100;i++){ins.runOnMainSync(()->{try{WebView web=(WebView)field(activity,"web");if(web!=null)web.evaluateJavascript(script,value::set);}catch(Exception e){throw new RuntimeException(e);}});Thread.sleep(100);if(expected.equals(value.get()))return;}assertEquals(expected,value.get());}
 @Test public void youtubeProtectionHidesOnlyKnownCardsWithoutTouchingVideoOrSkipControls()throws Exception{
  SharedPreferences prefs=c.getSharedPreferences(YouTubeProtection.PREF,0);boolean had=prefs.contains(YouTubeProtection.KEY),old=prefs.getBoolean(YouTubeProtection.KEY,true);prefs.edit().putBoolean(YouTubeProtection.KEY,true).commit();Activity activity=ins.startActivitySync(new Intent(c,YouTubeActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));String url="https://m.youtube.com/watch?v=aqz-KE-bpKQ",html="<html><head><meta name='viewport' content='width=device-width'></head><body><ytm-ad-slot-renderer id='ad'>Sponsored fixture</ytm-ad-slot-renderer><div id='content'>Onda • conteúdo de teste</div><video id='video' controls></video><button id='skip' class='ytp-ad-skip-button'>Pular anúncio</button></body></html>";
  try{ins.runOnMainSync(()->{try{WebView web=(WebView)field(activity,"web");web.stopLoading();web.loadDataWithBaseURL(url,html,"text/html","UTF-8",url);}catch(Exception e){throw new RuntimeException(e);}});String visible="getComputedStyle(document.getElementById('video')).display!=='none'&&getComputedStyle(document.getElementById('skip')).display!=='none'&&getComputedStyle(document.getElementById('content')).display!=='none'";waitBrowserScript(activity,"document.getElementById('ad')&&getComputedStyle(document.getElementById('ad')).display==='none'&&"+visible,"true");
   ins.runOnMainSync(()->{try{WebView web=(WebView)field(activity,"web");web.getWebViewClient().onPageFinished(web,url);web.evaluateJavascript("var a=document.createElement('ytm-ad-slot-renderer');a.id='later-ad';a.textContent='Later sponsored fixture';document.body.appendChild(a);",null);}catch(Exception e){throw new RuntimeException(e);}});waitBrowserScript(activity,"document.querySelectorAll('#onda-ad-protection').length===1&&getComputedStyle(document.getElementById('later-ad')).display==='none'","true");
   Bitmap shot=ins.getUiAutomation().takeScreenshot();if(shot!=null)try(OutputStream out=new FileOutputStream(new File(c.getFilesDir(),"youtube-protection-ui.png"))){shot.compress(Bitmap.CompressFormat.PNG,100,out);}finally{shot.recycle();}
   ins.runOnMainSync(()->{try{protection(activity,false);WebView web=(WebView)field(activity,"web");web.stopLoading();web.loadDataWithBaseURL(url,html,"text/html","UTF-8",url);}catch(Exception e){throw new RuntimeException(e);}});waitBrowserScript(activity,"document.getElementById('ad')&&getComputedStyle(document.getElementById('ad')).display!=='none'&&document.querySelectorAll('#onda-ad-protection').length===0&&"+visible,"true");
  }finally{ins.runOnMainSync(activity::finish);SharedPreferences.Editor edit=prefs.edit();if(had)edit.putBoolean(YouTubeProtection.KEY,old);else edit.remove(YouTubeProtection.KEY);edit.commit();}
 }

